// generation stats change.
//
// Emitted identically to src/lib/generated/ and cloud/src/generated/ —
// both packages read these rows and neither owns them.

// One map the community plays: what to call it, the script it runs, how
// it is set up, how few city sites it has been seen to spawn with, and
// the anchor that addresses it on the atlas.
//
// `name` carries the variant where the pool holds several of one script
// ("DOTA Jungle"); where two share a variant, `setting` is what tells
// them apart. `script` is the zType Old World declares — the same string
// games.map_class and tournament_matches.map_script carry, so it compares
// directly against a player's history. `anchor` is this map's identity:
// what a stored suggestion keeps, and what atlasAnchor() reproduces at
// runtime from a map_pool entry.
export interface AtlasPoolMap {
	anchor: string;
	script: string;
	name: string;
	setting: string;
	minSites: number;
}

